mapper.select:
SELECT COUNT(*) FROM footprints f
JOIN products p ON p.id = f.product_id AND p.deleted = 0
WHERE f.user_id = #{userId}

mapper.delete:
DELETE FROM footprints
WHERE user_id = #{userId}
  AND id NOT IN (
    SELECT id FROM (
                       SELECT id FROM footprints
                       WHERE user_id = #{userId}
                       ORDER BY updated_at DESC, id DESC
                       LIMIT #{keep}
                   ) t
)
